#!/usr/bin/env bash
# 人に判断を頼んだ問いと、オーナーの答えを対にして並べ、件数を数える(判断表 docs/judgment-criteria.md を育てる材料。#624)
#
# 使い方: judgment-history.sh <owner/repo> [<この日から。YYYY-MM-DD>]
#
# 標準出力に、タブ区切りで次を出す。
#   ask	<問いの URL>	<答えの URL か ->	<recommended|other|none>	<問いの 1 行目>
#   auto	<判断表で進めたコメントの URL>	<規則の ID>	<その後のオーナーの返信の URL か ->
#   summary	asks=<問い>	answered=<答えた>	recommended=<おすすめどおり>	auto=<判断表で進めた>	auto_replied=<その後に返信があった>
#
# - 問い: 目印 ai-dev:needs-human・ai-dev:needs-decision の付いたコメント。目印を信じるのは、オーナーと GitHub App が書いたものだけ
#   (public のリポジトリでは誰でも目印を書き込めるため。owner-answered.sh と同じ見分け方)
# - 答え: 問いの後、次の問いまでにオーナーが書いた最初のコメント。エージェント・自動の依頼もオーナーのアカウントで書くので、
#   目印 ai-dev: の付いたもの・「@coderabbitai」で始まるもの・Claude Code の署名の付いたものは答えに数えない
# - おすすめどおり: 答えに「おすすめ」がある、または答えの先頭の案の記号(A・B など)が、問いでおすすめとした案の記号と同じ。
#   問いの書き方は決まった形ではないので、数は目安。判断表に足す前に、問いと答えを読んで確かめる
# - 判断表で進めた: 目印 ai-dev:auto-judged の付いたコメント。その後、次のエージェントのコメントまでにオーナーの返信があれば、
#   戻してほしいと言われた候補として返信の URL を出す
set -euo pipefail

USAGE="使い方: judgment-history.sh <owner/repo> [<この日から。YYYY-MM-DD>]"

judgment_history() {
  local repo=${1:-} since=${2:-} owner query
  if [ -z "$repo" ] || [[ "$repo" != */* ]]; then
    echo "$USAGE" >&2
    return 2
  fi
  if [ -n "$since" ] && ! [[ "$since" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
    echo "$USAGE" >&2
    return 2
  fi
  owner=${repo%%/*}
  query="repos/$repo/issues/comments?per_page=100"
  [ -z "$since" ] || query="$query&since=${since}T00:00:00Z"
  gh api --paginate --slurp "$query" | pair_asks "$owner" "$since"
}

# 標準入力のコメント(--slurp でページの配列を 1 つの配列に入れたもの)から、問いと答えの対・判断表で進めた回を出す
pair_asks() {
  jq -r --arg owner "$1" --arg since "$2" '
    def trusted: .user.login == $owner or .user.type == "Bot";
    def by_owner: .user.login == $owner;
    def automated: (.body | test("ai-dev:|^\\s*@coderabbitai|Generated by \\[Claude Code\\]"));
    def is_ask: trusted and (.body | test("ai-dev:needs-(human|decision)"));
    def is_auto: trusted and (.body | test("ai-dev:auto-judged"));
    def is_answer: by_owner and (automated | not);
    def first_line: .body | gsub("<!--[^>]*-->"; "") | split("\n") | map(gsub("^[\\s#*]+|\\s+$"; "")) | map(select(. != "")) | (.[0] // "") | .[0:120];
    def rec_letter: .body | ((capture("(^|[\\s*(「\\[\"-]|案 ?)(?<l>[A-Z])([.:：)」*(（\\s]|$)[^\\n]{0,100}?おすすめ"; "x")
        // capture("おすすめ[^A-Z\\n]{0,16}(?<l>[A-Z])([^a-zA-Z]|$)") // {l: null}) | .l);
    def ans_letter: .body | ((capture("^\\s*\\**(?<l>[A-Z])\\**\\s*(で|$|[\\s。、,])") // {l: null}) | .l);
    def verdict($ask; $ans):
      if $ans == null then "none"
      elif ($ans.body | test("おすすめ")) then "recommended"
      elif ($ans | ans_letter) != null and ($ans | ans_letter) == ($ask | rec_letter) then "recommended"
      else "other" end;

    add // []
    | map(select($since == "" or .created_at >= $since))
    | group_by(.issue_url)
    | map(sort_by(.created_at)) as $issues
    | [ $issues[] as $c
        | range(0; $c | length) as $i
        | $c[$i] as $x
        | if ($x | is_ask) then
            ($c[$i + 1:] | (map(is_ask) | index(true)) as $next | if $next == null then . else .[0:$next] end) as $win
            | ($win | map(select(is_answer)) | .[0]) as $ans
            | {kind: "ask", url: $x.html_url, ans: ($ans.html_url // "-"), verdict: verdict($x; $ans), line: ($x | first_line)}
          elif ($x | is_auto) then
            ($c[$i + 1:] | (map(automated and trusted) | index(true)) as $next | if $next == null then . else .[0:$next] end) as $win
            | ($win | map(select(is_answer)) | .[0]) as $rep
            | {kind: "auto", url: $x.html_url,
               rule: ($x.body | (capture("ai-dev:auto-judged rule=(?<r>[A-Z]+-[0-9]+)") // {r: "-"}) | .r),
               reply: ($rep.html_url // "-")}
          else empty end ] as $rows
    | ($rows[] | if .kind == "ask" then [.kind, .url, .ans, .verdict, .line] else [.kind, .url, .rule, .reply] end | join("\t")),
      ([ "summary",
         "asks=\($rows | map(select(.kind == "ask")) | length)",
         "answered=\($rows | map(select(.kind == "ask" and .verdict != "none")) | length)",
         "recommended=\($rows | map(select(.verdict == "recommended")) | length)",
         "auto=\($rows | map(select(.kind == "auto")) | length)",
         "auto_replied=\($rows | map(select(.kind == "auto" and .reply != "-")) | length)" ] | join("\t"))
  '
}

judgment_history "$@"
